package com.trampolim.api.career;
import java.util.*;import java.time.*;import com.trampolim.api.radar.*;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class RegionalObservatory {
 private final JdbcTemplate jdbc;private final RadarBridge bridge;
 private record Entry(Instant expires,Map<String,Object> value){}private final Map<String,Entry> cache=new java.util.concurrent.ConcurrentHashMap<>();private final java.util.concurrent.Semaphore slots=new java.util.concurrent.Semaphore(4);private final com.trampolim.api.security.BoundedRateLimiter limiter=new com.trampolim.api.security.BoundedRateLimiter();
 @Value("${career.observatory-capture-enabled:true}")private boolean captureEnabled;
 public RegionalObservatory(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,RadarBridge bridge){this.jdbc=jdbc;this.bridge=bridge;}
 private String jobWhere(){return " FROM company_listings l JOIN companies c ON c.id=l.company_id LEFT JOIN company_career_context x ON x.listing_id=l.id WHERE "+com.trampolim.api.company.CompanyRadarController.PUBLIC_JOB_CONDITION;}
 @Scheduled(initialDelayString="${career.observatory-capture-delay-ms:3600000}",fixedDelayString="${career.observatory-capture-delay-ms:3600000}")public void scheduled(){if(captureEnabled)capture();}
 public void capture(){jdbc.update("INSERT INTO career_observatory_daily(region_code,day,open_jobs,future_demands) SELECT r.region,CURRENT_DATE,(SELECT count(*)"+jobWhere()+" AND UPPER(COALESCE(x.region_code,c.state))=r.region),(SELECT count(*) FROM company_future_demands d JOIN companies c ON c.id=d.company_id WHERE c.verification_status='APPROVED' AND d.status='PUBLISHED' AND d.hiring_end>=CURRENT_DATE AND UPPER(c.state)=r.region) FROM (SELECT DISTINCT UPPER(state) AS region FROM companies WHERE verification_status='APPROVED' AND length(state)=2) r ON CONFLICT(region_code,day) DO UPDATE SET open_jobs=EXCLUDED.open_jobs,future_demands=EXCLUDED.future_demands,observed_at=CURRENT_TIMESTAMP");jdbc.update("DELETE FROM career_observatory_daily WHERE day<CURRENT_DATE-INTERVAL '400 days'");}
 public Map<String,Object> dashboard(String region,String from,String to,String caller){CareerRules.dates(from,to);String uf=CareerRules.region(region,true),key=uf+":"+from+":"+to;var prior=cache.get(key);if(prior!=null&&prior.expires().isAfter(Instant.now()))return prior.value();if(!limiter.allow(caller,20,Duration.ofMinutes(1))||!slots.tryAcquire())throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Aguarde para consultar outra seleção de indicadores.");try{if(cache.size()>256)cache.entrySet().removeIf(e->e.getValue().expires().isBefore(Instant.now()));if(cache.size()>256)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Há muitas consultas analíticas em andamento.");var out=new LinkedHashMap<String,Object>();Object[] jobArgs={uf,uf,LocalDate.parse(from),LocalDate.parse(to).plusDays(1)};String jobs=jobWhere()+" AND (?='' OR UPPER(COALESCE(x.region_code,c.state))=?) AND l.created_at>=? AND l.created_at<?";
  out.put("region",uf);out.put("from",from);out.put("to",to);out.put("generatedAt",Instant.now().toString());out.put("companies",jdbc.queryForObject("SELECT count(DISTINCT c.id)"+jobs,Long.class,jobArgs));out.put("availableVacancies",jdbc.queryForObject("SELECT count(*)"+jobs,Long.class,jobArgs));out.put("vacanciesByRegion",jdbc.queryForList("SELECT UPPER(COALESCE(x.region_code,c.state)) AS region,count(*) AS vacancies"+jobs+" GROUP BY UPPER(COALESCE(x.region_code,c.state)) ORDER BY vacancies DESC,region LIMIT 28",jobArgs));out.put("occupations",jdbc.queryForList("SELECT l.title,count(*) AS vacancies"+jobs+" GROUP BY l.title ORDER BY vacancies DESC,l.title LIMIT 20",jobArgs));out.put("skills",jdbc.queryForList("SELECT s->>'skillCode' AS skill_code,count(*) AS vacancies"+jobs.replace(" WHERE "," LEFT JOIN company_radar_requirements rr ON rr.listing_id=l.id CROSS JOIN LATERAL jsonb_array_elements(rr.definition->'skills') s WHERE ")+" GROUP BY s->>'skillCode' ORDER BY vacancies DESC,skill_code LIMIT 20",jobArgs));out.put("companyRegionFallback",jdbc.queryForObject("SELECT count(*)"+jobs+" AND x.region_code IS NULL",Long.class,jobArgs));String forecasts=" FROM company_future_demands d JOIN companies c ON c.id=d.company_id WHERE d.status='PUBLISHED' AND c.verification_status='APPROVED' AND d.hiring_end>=CURRENT_DATE AND (?='' OR UPPER(c.state)=?) AND d.created_at>=? AND d.created_at<?";out.put("futureDemands",jdbc.queryForObject("SELECT count(*)"+forecasts,Long.class,jobArgs));out.put("estimatedHires",jdbc.queryForObject("SELECT COALESCE(sum(d.estimated_hires),0)"+forecasts,Long.class,jobArgs));var demands=jdbc.queryForList("SELECT d.id,(d.requirements->>'revision')::int AS revision"+forecasts+" ORDER BY d.id DESC LIMIT 200",jobArgs);var programs=jdbc.queryForList("SELECT p.id FROM hub_programs p JOIN enterprise_organizations o ON o.id=p.organization_id JOIN hub_profiles h ON h.organization_id=o.id WHERE p.status='PUBLISHED' AND p.ends_on>=CURRENT_DATE AND o.status='ACTIVE' AND h.published=TRUE ORDER BY p.id DESC LIMIT 200",Long.class);var query=new CareerRegionalController.Query(1,uf,from,to,demands.stream().map(r->new CareerRegionalController.Demand(((Number)r.get("id")).longValue(),((Number)r.get("revision")).intValue())).toList(),programs);try{out.put("qualification",bridge.convert(bridge.post("/integrations/career/observatory/candidates",query),Map.class));}catch(ResponseStatusException unavailable){out.put("qualification",Map.of("status","UNAVAILABLE"));}try{out.put("learning",bridge.convert(bridge.post("/integrations/career/observatory/learning",query),Map.class));}catch(ResponseStatusException unavailable){out.put("learning",Map.of("status","UNAVAILABLE"));}
  var confirmed=jdbc.queryForMap("SELECT count(*) AS confirmed,count(*) FILTER(WHERE p.published_at IS NOT NULL AND o.hire_date>=p.published_at::date) AS fill_sample,avg(o.hire_date-p.published_at::date) FILTER(WHERE p.published_at IS NOT NULL AND o.hire_date>=p.published_at::date) AS average_fill_days FROM company_selection_outcomes o JOIN company_applications a ON a.id=o.application_id JOIN company_listings l ON l.id=a.listing_id JOIN companies c ON c.id=l.company_id LEFT JOIN company_career_context x ON x.listing_id=l.id LEFT JOIN career_listing_publications p ON p.listing_id=l.id WHERE o.candidate_confirmed_at IS NOT NULL AND o.public_metrics_consent=TRUE AND (?='' OR UPPER(COALESCE(x.region_code,c.state))=?) AND o.candidate_confirmed_at>=? AND o.candidate_confirmed_at<?",jobArgs);long hires=((Number)confirmed.get("confirmed")).longValue();out.put("confirmedHires",CareerRules.band(hires));out.put("averageFillDays",((Number)confirmed.get("fill_sample")).longValue()>=10?confirmed.get("average_fill_days"):null);out.put("retention",null);out.put("history",jdbc.queryForList("SELECT day,sum(open_jobs) AS open_jobs,sum(future_demands) AS future_demands,max(observed_at) AS observed_at FROM career_observatory_daily WHERE (?='' OR region_code=?) AND day>=? AND day<=? GROUP BY day ORDER BY day LIMIT 366",uf,uf,LocalDate.parse(from),LocalDate.parse(to)));out.put("demandCoverage",Map.of("examined",demands.size(),"partial",((Number)out.get("futureDemands")).longValue()>demands.size()));out.put("publicProgramsCovered",programs.size());List<String> codes=new ArrayList<>();for(var row:(List<Map<String,Object>>)out.get("skills"))codes.add(row.get("skill_code").toString());if(codes.isEmpty())out.put("training",List.of());else try{out.put("training",bridge.convert(bridge.get("/public/capacita/radar/training?codes="+String.join(",",codes)),List.class));}catch(ResponseStatusException unavailable){out.put("training",List.of());out.put("trainingStatus","UNAVAILABLE");}out.put("notice","Amostra da plataforma, não estatística completa do mercado. Vagas/previsões: atualmente publicadas e criadas no período. Região usa UF informada ou base da empresa; previsões usam base empresarial. Participação e conclusões: coorte com consentimento específico no período, situação atual. Grupos pessoais menores que dez são suprimidos. Evolução diária só existe desde a captura real após esta versão; não foi reconstruída. Estimativas, relatos e confirmações têm significados distintos. Custos privados não aparecem neste painel público.");cache.put(key,new Entry(Instant.now().plusSeconds(60),out));return out;
 }finally{slots.release();}}
}
